`ifndef MULT_TRANSACTION 
`define MULT_TRANSACTION

class mult_transaction extends uvm_sequence_item;
  //////////////////////////////////////////////////////////////////////////////
  // Declaration of mult transaction fields
  //////////////////////////////////////////////////////////////////////////////
   rand bit [`MULT_WIDTH-1:0] x,y;
   bit [(`MULT_WIDTH*2)-1:0] result; 
  //////////////////////////////////////////////////////////////////////////////
  //Declaration of Utility and Field macros,
  //////////////////////////////////////////////////////////////////////////////
  `uvm_object_utils_begin(mult_transaction)
    `uvm_field_int(x,UVM_ALL_ON)
    `uvm_field_int(y,UVM_ALL_ON)
    `uvm_field_int(result,UVM_ALL_ON)
  `uvm_object_utils_end
   
  //////////////////////////////////////////////////////////////////////////////
  //Constructor
  //////////////////////////////////////////////////////////////////////////////
  function new(string name = "mult_transaction");
    super.new(name);
  endfunction
  //////////////////////////////////////////////////////////////////////////////
  // Declaration of Constraints
  //////////////////////////////////////////////////////////////////////////////
  //constraint x_c {x inside {[4'h0:4'hF]}; }			  
  //constraint y_c {y inside {[4'h0:4'hF]}; }
  //////////////////////////////////////////////////////////////////////////////
  // Method name : post_randomize();
  // Description : To display transaction info after randomization
  //////////////////////////////////////////////////////////////////////////////
  function void post_randomize();
  endfunction  
   
endclass


`endif


